package com.dispatchpro.driver;
import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.media.*;
import android.os.*;
/** Starts only after a visible user call action. Owns audio focus and microphone FGS lifetime. */
public final class CallAudioService extends Service {
 public static boolean running,requested;private static Activity host;private AudioManager audio;private AudioFocusRequest focus;private int previousMode;private boolean previousSpeaker;private AudioDeviceInfo previousCommunicationDevice;private String callId="";
 public static void begin(Activity activity,String id,boolean speaker,String rideId,String peerName){host=activity;requested=true;Intent intent=new Intent(activity,CallAudioService.class).putExtra("callId",id).putExtra("speaker",speaker).putExtra("rideId",rideId).putExtra("peerName",peerName);try{if(Build.VERSION.SDK_INT>=26)activity.startForegroundService(intent);else activity.startService(intent);}catch(RuntimeException denied){requested=false;host=null;throw denied;}}
 public static void end(Context c){requested=false;c.stopService(new Intent(c,CallAudioService.class));}
 static void endFromNotification(Context c){if(host!=null){Activity current=host;current.runOnUiThread(()->{if(current instanceof MainActivity)((MainActivity)current).callFocusLost();if(current instanceof CustomerActivity)((CustomerActivity)current).callFocusLost();});}end(c);}
 @Override public void onCreate(){super.onCreate();audio=getSystemService(AudioManager.class);previousMode=audio.getMode();previousSpeaker=audio.isSpeakerphoneOn();if(BuildConfig.DRIVER_QA&&Build.VERSION.SDK_INT>=31)try{previousCommunicationDevice=audio.getCommunicationDevice();}catch(RuntimeException unavailable){previousCommunicationDevice=null;android.util.Log.w("DriverAudio","Previous call device unavailable");}}
 @Override public int onStartCommand(Intent i,int flags,int startId){if(!BuildConfig.DRIVER_QA)return startCall(i,flags,startId);try{return startCall(i,flags,startId);}catch(RuntimeException failure){android.util.Log.w("DriverAudio","Call audio route unavailable");endFromNotification(this);return START_NOT_STICKY;}}
 private int startCall(Intent i,int flags,int startId){if(i==null){stopSelf();return START_NOT_STICKY;}callId=i.getStringExtra("callId");CommunicationNotifications.configure(this);if(BuildConfig.DRIVER_QA)QaSounds.stop(this);if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("ride_call_service_v1","خدمة مكالمة الرحلة",NotificationManager.IMPORTANCE_LOW));Intent end=new Intent(this,CallActionReceiver.class).setAction("end").setData(android.net.Uri.parse("dispatchpro://end/"+callId)).putExtra("callId",callId);PendingIntent stop=PendingIntent.getBroadcast(this,0,end,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"ride_call_service_v1"):new Notification.Builder(this);b.setSmallIcon(R.drawable.ic_driver).setContentTitle(PushDisplayPolicy.name(i.getStringExtra("peerName"))).setContentIntent(CommunicationNotifications.open(this,i.getStringExtra("rideId")==null?"":i.getStringExtra("rideId"),callId,"open")).setCategory(Notification.CATEGORY_CALL).setContentText("الميكروفون مستخدم للمكالمة").setOngoing(true).setOnlyAlertOnce(true).setSound(null).addAction(new Notification.Action.Builder(null,"إنهاء",stop).build());
  try{if(Build.VERSION.SDK_INT>=29)startForeground(8201,b.build(),ServiceInfo.FOREGROUND_SERVICE_TYPE_MICROPHONE);else startForeground(8201,b.build());}catch(RuntimeException denied){endFromNotification(this);return START_NOT_STICKY;}
  if(!running){AudioAttributes attributes=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_VOICE_COMMUNICATION).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build();int grant;if(Build.VERSION.SDK_INT>=26){focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT).setAudioAttributes(attributes).setOnAudioFocusChangeListener(change->{if(change==AudioManager.AUDIOFOCUS_LOSS||change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT)endFromNotification(this);}).build();grant=audio.requestAudioFocus(focus);}else grant=audio.requestAudioFocus(change->{if(change<0)endFromNotification(this);},AudioManager.STREAM_VOICE_CALL,AudioManager.AUDIOFOCUS_GAIN_TRANSIENT);if(grant!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){endFromNotification(this);return START_NOT_STICKY;}audio.setMode(AudioManager.MODE_IN_COMMUNICATION);running=true;}
  route(i.getBooleanExtra("speaker",false));return START_NOT_STICKY;
 }
 private boolean select(AudioDeviceInfo d){return BuildConfig.DRIVER_QA?CommunicationRoute.select(audio,d):audio.setCommunicationDevice(d);}
 private void route(boolean speaker){if(Build.VERSION.SDK_INT>=31){audio.clearCommunicationDevice();if(!speaker)for(AudioDeviceInfo d:audio.getAvailableCommunicationDevices())if(d.getType()==AudioDeviceInfo.TYPE_BLUETOOTH_SCO||d.getType()==AudioDeviceInfo.TYPE_BLE_HEADSET||d.getType()==AudioDeviceInfo.TYPE_WIRED_HEADSET||d.getType()==AudioDeviceInfo.TYPE_USB_HEADSET){if(select(d))return;}int type=speaker?AudioDeviceInfo.TYPE_BUILTIN_SPEAKER:AudioDeviceInfo.TYPE_BUILTIN_EARPIECE;for(AudioDeviceInfo d:audio.getAvailableCommunicationDevices())if(d.getType()==type){select(d);break;}}else audio.setSpeakerphoneOn(speaker);}
 @Override public IBinder onBind(Intent i){return null;}
 private void restore(){if(Build.VERSION.SDK_INT>=26&&focus!=null)audio.abandonAudioFocusRequest(focus);else audio.abandonAudioFocus(null);try{if(Build.VERSION.SDK_INT>=31){if(BuildConfig.DRIVER_QA)CommunicationRoute.restore(audio,previousCommunicationDevice);else audio.clearCommunicationDevice();}else audio.setSpeakerphoneOn(previousSpeaker);}finally{audio.setMode(previousMode);previousCommunicationDevice=null;}}
 @Override public void onDestroy(){running=false;requested=false;if(BuildConfig.DRIVER_QA){QaSounds.ringback(this,false);try{if(audio!=null)restore();}catch(RuntimeException ignored){android.util.Log.w("DriverAudio","Call audio restoration unavailable");}}else if(audio!=null)restore();Activity finished=host;host=null;if(finished instanceof MainActivity)((MainActivity)finished).closeEngineIfDestroyed();if(finished instanceof CustomerActivity)((CustomerActivity)finished).closeEngineIfDestroyed();super.onDestroy();}
}
